package org.codex.nfsugpreview;
import java.io.*;import java.nio.*;import java.nio.file.*;import java.util.*;
public final class SourceRoadProjectionTest {
 public static void main(String[] args)throws Exception{byte[] table=Files.readAllBytes(Paths.get(args[0]));NativeRoadProjection helper=new NativeRoadProjection(ByteBuffer.wrap(table));table[4]^=1;int accepted=0,rejected=0,rings=0,points=0,near=0,total;double maximum=0;try(DataInputStream in=new DataInputStream(new FileInputStream(args[1]))){if(in.readInt()!=0x31505352)throw new AssertionError("Header");total=in.readInt();for(int c=0;c<total;c++){int type=in.readInt(),shift=in.readInt(),height=in.readInt(),affine=in.readInt(),count=in.readInt();int[] projection={in.readInt(),in.readInt(),in.readInt()},matrix=new int[12];for(int i=0;i<12;i++)matrix[i]=in.readInt();double[][] input=new double[count][5],before=new double[count][5];for(int i=0;i<count;i++)for(int k=0;k<5;k++)before[i][k]=input[i][k]=in.readDouble();boolean expected=in.readInt()!=0;int length=in.readInt();double[][] reference=new double[length][5];for(int i=0;i<length;i++)for(int k=0;k<5;k++)reference[i][k]=in.readDouble();boolean good=true;double[][] actual=null;try{if(type==0){points++;actual=new double[][]{helper.point(input[0],new double[]{input[0][3],input[0][4]},shift,height,projection)};}else if(type==1){near++;actual=new double[][]{helper.near(input[0],input[1],64)};}else{rings++;ByteBuffer raw=ByteBuffer.allocate(288).order(ByteOrder.LITTLE_ENDIAN),camera=ByteBuffer.allocate(56).order(ByteOrder.LITTLE_ENDIAN);raw.putInt(0,count).putInt(4,shift).putInt(8,height).putInt(12,affine);camera.putInt(1).putInt(0x02000000);for(int v:matrix)camera.putInt(v);double[][] world=new double[count][3];for(int i=0;i<count;i++){System.arraycopy(input[i],0,world[i],0,3);raw.putInt(32+i*8,(int)input[i][3]).putInt(36+i*8,(int)input[i][4]);}actual=helper.ring(world,raw,new NativeRoadCamera((ByteBuffer)camera.rewind()),projection);}}catch(IllegalArgumentException invalid){good=false;}if(good!=expected)throw new AssertionError("Acceptance case "+c+" type "+type);if(!Arrays.deepEquals(input,before))throw new AssertionError("Input mutation");if(good){accepted++;if(actual.length!=length)throw new AssertionError("Ring count "+c);for(int i=0;i<length;i++)for(int k=0;k<5;k++){double error=Math.abs(actual[i][k]-reference[i][k]);maximum=Math.max(maximum,error);if(!Double.isFinite(error)||error>1e-12*Math.max(1,Math.abs(reference[i][k])))throw new AssertionError("Coordinate case "+c+" vertex "+i+" channel "+k+" actual "+actual[i][k]+" expected "+reference[i][k]);}}else rejected++;}if(in.read()!=-1)throw new AssertionError("Trailing data");}System.out.println("PASS_SOURCE_ROAD_PROJECTION cases="+total+" accepted="+accepted+" rejected="+rejected+" point_cases="+points+" near_cases="+near+" ring_cases="+rings+" max_difference="+maximum+" input_immutable=true table_owned=true");}
}
